package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.regex.Pattern;

/**
 * Normalizes a street address to a canonical stored form.
 *
 * <p>Rules: trim the ends, collapse every run of whitespace to a single space, upper-case the
 * whole string, then expand common abbreviations as whole words: {@code ST -> STREET},
 * {@code RD -> ROAD}, {@code AVE -> AVENUE}. Expansion is token-based, so an abbreviation embedded
 * in a longer word (e.g. {@code STANMORE}) is left untouched. A {@code null} or all-whitespace
 * input yields the empty string, which the required-field check treats as a blank address.
 *
 * <p>Example: {@code "  12  main  st "} becomes {@code "12 MAIN STREET"}.
 */
final class AddressNormalizer {

    /** Any run of whitespace, collapsed to a single space. */
    private static final Pattern WHITESPACE = Pattern.compile("\\s+");

    private AddressNormalizer() {
    }

    /** Convert to the canonical stored form; {@code null}/blank input yields {@code ""}. */
    static String normalize(String raw) {
        if (raw == null) {
            return "";
        }
        String collapsed = WHITESPACE.matcher(raw.trim()).replaceAll(" ").toUpperCase(Locale.ROOT);
        if (collapsed.isEmpty()) {
            return "";
        }
        String[] tokens = collapsed.split(" ");
        StringBuilder sb = new StringBuilder(collapsed.length());
        for (int i = 0; i < tokens.length; i++) {
            if (i > 0) {
                sb.append(' ');
            }
            sb.append(expand(tokens[i]));
        }
        return sb.toString();
    }

    /** Expand a single whole-word abbreviation, or return the token unchanged. */
    private static String expand(String token) {
        switch (token) {
            case "ST":
                return "STREET";
            case "RD":
                return "ROAD";
            case "AVE":
                return "AVENUE";
            default:
                return token;
        }
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.regex.Pattern;

import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DisposableEmailDomainException;
import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Binds the owner body and rejects it when any required field is missing or blank, so an
 * invalid body is a 400 (listing the offending field names) even when the owner does not exist.
 * Also normalizes the telephone to E.164 form (see {@link TelephoneE164}), publishing the
 * normalized value so it is stored and returned as {@code telephone}.
 * The address is normalized (see {@link AddressNormalizer}) before the required-field check, so a
 * value that is blank only after normalization is rejected, and the normalized form is stored and
 * returned as {@code address}.
 * The optional email is accepted when absent; when present it must be a syntactically valid
 * address (else 400) whose domain is not on the disposable-domain blocklist (else 400), and is
 * lower-cased so it is stored and returned as {@code email}.
 * Runs before {@link LoadOwner}/{@link BuildOwner} and publishes the body for later steps.
 */
public class ValidateOwner {

    /** Syntactic email check: a non-empty local part, an '@', then a dotted domain. */
    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s.]+(\\.[^@\\s.]+)+$");

    /** A valid postcode is exactly four digits. */
    private static final Pattern POSTCODE = Pattern.compile("^[0-9]{4}$");

    /** Disposable email domains that are never accepted, even when syntactically valid. */
    private static final Set<String> DISPOSABLE_DOMAINS =
            Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");

    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
            throws MissingOwnerFieldsException, InvalidTelephoneException, InvalidEmailException,
            DisposableEmailDomainException, InvalidPostcodeException {
        List<String> missing = new ArrayList<>();
        if (isBlank(request.getFirstName())) {
            missing.add("firstName");
        }
        if (isBlank(request.getLastName())) {
            missing.add("lastName");
        }
        // Normalize the address before the required-field check, so an address that is blank
        // only after normalization is rejected, and the normalized value is stored and returned.
        request.setAddress(AddressNormalizer.normalize(request.getAddress()));
        if (isBlank(request.getAddress())) {
            missing.add("address");
        }
        if (isBlank(request.getCity())) {
            missing.add("city");
        }
        if (isBlank(request.getTelephone())) {
            missing.add("telephone");
        }
        if (!missing.isEmpty()) {
            throw new MissingOwnerFieldsException(missing);
        }
        // Normalize telephone to E.164; reject anything that cannot form a valid number.
        String e164 = TelephoneE164.normalize(request.getTelephone());
        if (e164 == null) {
            throw new InvalidTelephoneException(request.getTelephone());
        }
        request.setTelephone(e164);
        // Email is optional. When present it must be syntactically valid; store it lower-cased.
        String email = request.getEmail();
        if (email != null && !email.isBlank()) {
            String normalized = email.trim().toLowerCase();
            if (!EMAIL.matcher(normalized).matches()) {
                throw new InvalidEmailException(email);
            }
            // Reject syntactically valid addresses whose domain is a known disposable provider.
            String domain = normalized.substring(normalized.indexOf('@') + 1);
            if (DISPOSABLE_DOMAINS.contains(domain)) {
                throw new DisposableEmailDomainException(email);
            }
            request.setEmail(normalized);
        }
        // Postcode is optional. When present it must be four digits and, when the city maps to a
        // known region, fall within that region's range; a city with no known region accepts any
        // 4-digit postcode. The (trimmed) value is stored and returned as given.
        String postcode = request.getPostcode();
        if (postcode != null && !postcode.isBlank()) {
            String trimmed = postcode.trim();
            if (!POSTCODE.matcher(trimmed).matches()) {
                throw new InvalidPostcodeException(postcode);
            }
            int[] range = CityRegion.postcodeRangeOf(request.getCity());
            if (range != null) {
                int value = Integer.parseInt(trimmed);
                if (value < range[0] || value > range[1]) {
                    throw new InvalidPostcodeException(postcode);
                }
            }
            request.setPostcode(trimmed);
        }
        validated.set(request);
    }

    private static boolean isBlank(String value) {
        return value == null || value.isBlank();
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns the owner's deterministic {@code householdId}: the first 12 upper-case hex characters of
 * SHA-256 over the normalized last name and postcode (see {@link OwnerIdentity#householdIdFor}).
 *
 * <p>The identifier is derived purely from {@code (lastName, postcode)}, so owners with the same last
 * name and postcode share it automatically, regardless of creation order and regardless of whether
 * they opted in with {@code sharesHousehold} — that flag now only bypasses the duplicate block (see
 * {@link CheckIdentityUnique}), it no longer creates the link. An owner without a postcode is not in
 * any household and is left with no identifier.
 *
 * <p>Runs after {@link BuildOwner} (which publishes the new owner) and before {@link SaveOwner}.
 */
public class AssignHousehold {

    public void service(@Val Owner owner) {
        owner.setHouseholdId(OwnerIdentity.householdIdFor(owner.getLastName(), owner.getPostcode()));
    }
}

